/** Test helper: the generated files the repo committed, with the img2cpc.py command line from their headers. */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { shellSplit } from './cpcimp';
import { REPO } from './testutil';

/** Every committed file the repo generated with img2cpc.py: [file, its argv]. */
export function committed(): [string, string[]][] {
  const out: [string, string[]][] = [];
  const walk = (dir: string): void => {
    for (const e of fs.readdirSync(path.join(REPO, dir), { withFileTypes: true })) {
      const rel = `${dir}/${e.name}`;
      if (e.isDirectory()) walk(rel);
      else if (e.name.endsWith('.bas')) {
        const first = fs.readFileSync(path.join(REPO, rel), 'utf8').split('\n', 1)[0];
        const m = /^' Generated by img2cpc\.py (.*)$/.exec(first);
        if (m) out.push([rel, shellSplit(m[1])]);
      }
    }
  };
  for (const d of CORPUS_DIRS) walk(d);
  return out;
}

/** The directories scanned, and every file the recipes need (images, palettes). */
export const CORPUS_DIRS = ['examples/assets', 'tests/conformance/assets', 'games/shooter/assets'];
